ALTER TABLE public.students ADD COLUMN IF NOT EXISTS photo_path text;
ALTER TABLE public.attendance DROP CONSTRAINT IF EXISTS attendance_method_check;
ALTER TABLE public.attendance ADD CONSTRAINT attendance_method_check CHECK (method IN ('manual','biometric','biometric_sim','device_sync','ai_photo'));
CREATE POLICY "Attendance staff reads owner students" ON public.students FOR SELECT TO authenticated USING (user_id = public.get_owner_id(auth.uid()) AND public.staff_has_permission(auth.uid(), 'attendance'));
CREATE POLICY "Attendance staff reads owner batches" ON public.batches FOR SELECT TO authenticated USING (user_id = public.get_owner_id(auth.uid()) AND public.staff_has_permission(auth.uid(), 'attendance'));
CREATE POLICY "Workspace reads private member photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'member-photos' AND ((storage.foldername(name))[1] = auth.uid()::text OR ((storage.foldername(name))[1] = public.get_owner_id(auth.uid())::text AND (public.staff_has_permission(auth.uid(), 'customers') OR public.staff_has_permission(auth.uid(), 'attendance')))));
CREATE POLICY "Member editors upload private photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'member-photos' AND ((storage.foldername(name))[1] = auth.uid()::text AND public.has_role(auth.uid(), 'owner') OR (storage.foldername(name))[1] = public.get_owner_id(auth.uid())::text AND public.staff_has_permission(auth.uid(), 'customers')) AND EXISTS (SELECT 1 FROM public.students s WHERE s.id::text = (storage.foldername(name))[2] AND s.user_id::text = (storage.foldername(name))[1]));
CREATE POLICY "Member editors remove private photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'member-photos' AND ((storage.foldername(name))[1] = auth.uid()::text AND public.has_role(auth.uid(), 'owner') OR (storage.foldername(name))[1] = public.get_owner_id(auth.uid())::text AND public.staff_has_permission(auth.uid(), 'customers')));